algorithms.pseudocode:
def build(queries, k=10):
    root = Node()
    for q, score in queries:
        n = root
        for ch in q: n = n.children.setdefault(ch, Node())
        n.terminal = (q, score)
    def fill(n):
        cands = [n.terminal] if n.terminal else []
        for c in n.children.values():
            fill(c); cands.extend(c.topk)
        n.topk = heapq.nlargest(k, cands, key=lambda x: x[1])
    fill(root)
    return root
